/* @autogenerated */
import { Directive, effect, input, Signal, signal, untracked } from '@angular/core';
import { FormGroup, ValidationErrors } from '@angular/forms';
import { Subscription } from 'rxjs';
import { BaseEditable } from './base-editable';
import { ContextFields } from '@shared/data/repository/context-filter';

/**
 * Cómo usa un formulario el contexto de su entidad: `edit` rellena y bloquea los campos fijos y rellena los
 * vacíos con los valores por defecto; `view` solo oculta los fijos; `search` oculta los filtros que ya aplica.
 */
export type ContextUse = 'edit' | 'view' | 'search';

@Directive({})
export abstract class SubFormEditable<T> extends BaseEditable<T> {
  private bindSubscription?: Subscription;
  hidden = input<string[] | undefined>([]);
  fixed = input<string[] | undefined>([]);
  defined = input<{ [key: string]: any }>();
  definedFixed = signal<string[]>([]);
  definedHidden = signal<string[]>([]);

  isVisible = {} as { [key: string]: boolean };
  isEditable = {} as { [key: string]: boolean };
  outerValue: any;
  // Use false to show fixed fields.
  hideContextSelection = true;
  /** Campos que fija el contexto de la entidad (ver {@link useContext}). */
  readonly contextFixedFields = signal<string[]>([]);
  /** Valores del contexto que se ponen en el formulario (solo con `useContext(..., 'edit')`). */
  private contextValues: Pick<ContextFields, 'fixed' | 'defaults'> = { fixed: {}, defaults: {} };
  defaultValues: () => T = () => {
    return {} as T;
  };

  constructor(public readonly form: FormGroup) {
    super();

    effect(() => {
      const paramFixed = this.fixed() || [];
      const progFixed = this.definedFixed();
      const fixed = [...paramFixed, ...progFixed, ...this.contextFixedFields()];
      if (this.form.controls) {
        Object.entries(this.form.controls).forEach(([name, control]) => {
          this.isEditable[name] = !fixed.includes(name);
          setTimeout(() => {
            if (this.control.disabled) {
              control.disable({ onlySelf: true });
            } else if (fixed.includes(name) && control.enabled) {
              control.disable({ onlySelf: true });
            } else if (!fixed.includes(name) && control.disabled) {
              control.enable({ onlySelf: true });
            }
          });
        });
      }
    });
    effect(() => {
      const paramHiddens = this.hidden() || [];
      const progHiddens = this.definedHidden();
      const conextHidends = this.hideContextSelection ? this.contextFixedFields() : [];
      const hiddens = [...paramHiddens, ...progHiddens, ...conextHidends];
      if (this.form.controls) {
        Object.keys(this.form.controls).forEach((name) => {
          this.isVisible[name] = !hiddens.includes(name);
        });
      }
    });
  }

  /**
   * Aplica el contexto de la entidad, tal como lo resuelve su repositorio (`repository.context()`): el formulario
   * generado lo llama en su constructor. Solo se tocan los controles que existen en el formulario.
   */
  protected useContext(context: Signal<ContextFields>, use: ContextUse = 'edit'): void {
    effect(() => {
      const current = context();
      const own = (fields: string[]) => fields.filter((name) => !!this.form.get(name));
      if (use === 'search') {
        this.contextFixedFields.set(own(current.filtered));
        return;
      }
      this.contextFixedFields.set(own(Object.keys(current.fixed)));
      if (use === 'edit') {
        this.contextValues = current;
        untracked(() => {
          const raw = this.form.getRawValue();
          const patch = this.withContext(raw);
          const changed = Object.keys(patch).filter((name) => patch[name] !== raw[name]);
          if (changed.length) {
            this.form.patchValue(Object.fromEntries(changed.map((name) => [name, patch[name]])));
            this.form.updateValueAndValidity({});
          }
        });
      }
    });
  }

  override ngOnInit() {
    super.ngOnInit();
    this.control.valueChanges.subscribe((value) => {
      this.assignData(value);
    });
    this.bindSubscription?.unsubscribe();
    this.bindSubscription = this.form.valueChanges.subscribe((val) => {
      const value = this.form.getRawValue();
      if (this.form?.dirty) {
        this.updateValue(value);
      }
      this.syncFormStatus();
    });
    this.form.statusChanges.subscribe((value) => {
      this.syncFormStatus();
    });
  }

  override ngOnDestroy() {
    super.ngOnDestroy();
    this.bindSubscription?.unsubscribe();
  }

  protected assignData(assigned: any) {
    const value = assigned ?? this.defaultValues();
    const defined = this.defined();
    const filled = { ...((value as any) || {}), ...defined };
    const paramKeys = [...(defined ? Object.keys(defined) : []), ...(value ? Object.keys(value) : [])];
    Object.keys(this.form.controls).forEach((name) => {
      if (!paramKeys.includes(name)) {
        if (!this.isEditable[name]) {
          filled[name] = this.form.controls[name].value;
        } else {
          filled[name] = null;
        }
      }
    });
    Object.assign(filled, this.withContext(filled));
    Object.keys(filled).forEach((name) => {
      if (!this.form.get(name)) {
        delete filled[name];
      }
    });
    const old = JSON.stringify(this.outerValue);
    const upd = JSON.stringify(filled);
    if (old !== upd) {
      this.outerValue = filled;
      this.form.patchValue(filled, { onlySelf: true });
      this.value.set(filled);
    }
  }

  /** `value` con los valores fijos del contexto y, en los campos vacíos, los de por defecto. */
  private withContext(value: Record<string, any>): Record<string, any> {
    const result = { ...value, ...this.contextValues.fixed };
    Object.entries(this.contextValues.defaults).forEach(([name, ctx]) => {
      if (isEmpty(result[name])) {
        result[name] = ctx;
      }
    });
    return result;
  }

  private syncFormStatus() {
    if (this.form?.dirty) {
      this.pending.set(this.form.pending);
      const errors = JSON.stringify(this.errors());
      const newErrors = {} as ValidationErrors;
      Object.entries(this.form.controls).forEach(([name, control]) => {
        if (control.errors) {
          Object.entries(control.errors).forEach(([lb, ms]) => {
            newErrors[name + '.' + lb] = ms;
          });
        }
      });
      if (errors !== JSON.stringify(newErrors)) {
        this.errors.set(newErrors);
      }
    }
  }
}

function isEmpty(value: unknown): boolean {
  return value === undefined || value === null || value === '' || (typeof value === 'object' && !(value as any).$ref);
}
